  if(!api||!root.classList.contains('cinema-gl-ready'))fallback();
  if(api){api.gl.clear(api.gl.COLOR_BUFFER_BIT);const planeX=mobile?.78:.57,planeY=.89;api.v2('uPlane',planeX,planeY);api.v2('uPointer',pointer.x,pointer.y);api.f('uBend',Math.max(-.14,Math.min(.14,velocity*.035)));api.f('uPlaneAspect',stageWidth*planeX/(stageHeight*planeY));drawOrder.sort((a,b)=>Math.abs(distance(b))-Math.abs(distance(a)));let drawn=0;for(const i of drawOrder){if(Math.abs(distance(i))>=1.8)continue;const item=textures.get(i);if(!item){load(i);continue;}api.bind(item.texture);api.f('uDistance',distance(i));api.f('uImageAspect',item.width/item.height);api.f('uFocal',Number(slides[i].dataset.focal)/100||.5);api.draw();drawn++;}if(drawn&&textures.has(mod(index))){root.classList.add('cinema-gl-ready');loaded=true;}canvas.dataset.textures=String(textures.size);canvas.dataset.draws=String(drawn);}
