 const onDown=event=>{if(event.button!==0||event.target.closest('button,a'))return;stageRect=stage.getBoundingClientRect();dragging=true;startX=event.clientX;startIndex=current;dragDelta=0;stage.setPointerCapture?.(event.pointerId);stage.classList.add('is-dragging');};
